import * as T from 'three';
import config from '../project.config.js';
import {buildScene}from'../scene.js';
import{createRuntime}from'./core/runtime.js';
import{createRandom}from'./core/random.js';
import{createSignage}from'./world/signage.js';
import{createProps}from'./world/props.js';
import{createActors}from'./actors/models.js';
import{createChongqingLife}from'./chongqing/life.js';
import{createChongqingLighting}from'./chongqing/lighting.js';
import{createSoftWater}from'./chongqing/soft-water.js';
try{
 await document.fonts.ready;
 const ctx=createRuntime(config);ctx.signage=createSignage(ctx);ctx.props=createProps(ctx);const layout=buildScene(ctx);ctx.batch.flush();
 const statics=ctx.scene.children.filter(o=>o.isMesh&&!o.isInstancedMesh),actors=createActors({...ctx,...createRandom(815500)}),life=createChongqingLife(ctx,layout,actors),simulation=life,lighting=createChongqingLighting(ctx);
 const water=createSoftWater({scene:ctx.scene,renderer:ctx.renderer,camera:ctx.camera,...layout.water,reflectionSources:statics,lights:lighting.lights,selectTriangle:({centroid,minY})=>minY>.3&&centroid.y<40&&centroid.z>-16,reflectionStrength:.12,reflectionGrazing:.18,reflectionBlur:1.4,distortion:.0007,targetScale:ctx.economy?.32:.45,targetCap:ctx.economy?320:560,waveAmplitude:.007,waveUnit:1.7,waterColor:'#738b82',skyColor:'#bdcbd1'});
 let fly=null,lastColors=lighting.update(0),toastTimer;
 function toast(s){const e=document.querySelector('#toast');e.textContent=s;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),2600);}
 function refresh(){const{state}=ctx;document.body.dataset.time=state.timeMode;document.body.classList.toggle('night',state.timeMode==='night');document.querySelector('#time span').textContent={day:'Day',sunset:'Sunset',night:'Night'}[state.timeMode];document.querySelector('#time').setAttribute('aria-label','Current lighting: '+state.timeMode+'; change lighting');document.querySelector('#time svg').innerHTML=state.timeMode==='night'?'<path d="M19.5 15.5A8 8 0 0 1 8.5 4.5 8 8 0 1 0 19.5 15.5Z"/>':state.timeMode==='sunset'?'<path d="M3 17h18M5 21h14M6 13a6 6 0 0 1 12 0M12 2v3M3 6l2 2m16-2-2 2"/>':'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>';for(const [id,on]of[['orbit',state.orbit],['fog',state.fogOn],['lights',state.lightsOn],['pause',state.paused]])document.querySelector('#'+id).setAttribute('aria-pressed',String(on));document.querySelector('#pause span').textContent=state.paused?'Play':'Pause';for(const kind of['traffic','people']){const b=document.querySelector('#'+kind);b.dataset.mode=state[kind+'Mode'];b.setAttribute('aria-pressed',String(state[kind+'Mode']==='active'));b.setAttribute('aria-label',kind+' '+state[kind+'Mode']+'; click for next state');}document.querySelector('#status').textContent=state.paused?'A quiet moment, held still.':state.timeMode==='night'?'River lights. Warm timber balconies.':state.timeMode==='sunset'?'The last sun reaches the river.':'The mountain city is waking up.';}
 const presets={city:{p:config.camera.position,t:config.camera.target,zoom:1},liziba:{p:[-26.1,36.25,29],t:[-14.5,14.5,0],zoom:1},hongya:{p:[26.1,21.75,44.95],t:[-4.35,7.25,7.25],zoom:1}};
 function focus(name){const v=presets[name];if(!v)return;ctx.cancelReset();ctx.setOrbit(false);if(matchMedia('(prefers-reduced-motion: reduce)').matches){ctx.camera.position.set(...v.p);ctx.controls.target.set(...v.t);ctx.camera.zoom=v.zoom*ctx.fitZoom;ctx.camera.updateProjectionMatrix();ctx.controls.update();document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===name)));refresh();return;}fly={p:ctx.camera.position.clone(),t:ctx.controls.target.clone(),zoom:ctx.camera.zoom,to:new T.Vector3(...v.p),target:new T.Vector3(...v.t),z:v.zoom,start:performance.now()};document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===name)));refresh();}
 document.querySelector('#time').onclick=()=>{ctx.state.timeMode={day:'sunset',sunset:'night',night:'day'}[ctx.state.timeMode];ctx.state.night=ctx.state.timeMode==='night';refresh();};document.querySelector('#orbit').onclick=()=>{ctx.setOrbit(!ctx.state.orbit);refresh();};document.querySelector('#fog').onclick=()=>{ctx.state.fogOn=!ctx.state.fogOn;refresh();};document.querySelector('#lights').onclick=()=>{ctx.state.lightsOn=!ctx.state.lightsOn;refresh();};document.querySelector('#train').onclick=()=>{life.call();toast('Next train approaching Liziba.');};document.querySelector('#pause').onclick=()=>{ctx.state.paused=!ctx.state.paused;refresh();};document.querySelector('#reset').onclick=()=>focus('city');for(const kind of['traffic','people'])document.querySelector('#'+kind).onclick=()=>{simulation.cycle(kind);refresh();};document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>focus(b.dataset.view));ctx.controls.addEventListener('start',()=>fly=null);
 addEventListener('keydown',e=>{if(e.target.matches('button,input,select,textarea'))return;if(e.code==='Space'){e.preventDefault();ctx.state.paused=!ctx.state.paused;refresh();}if(e.key==='Home')focus('city');});
 ctx.beforeRender=()=>{water.update({time:ctx.state.time,...lastColors});water.capture();};
 refresh();ctx.start(dt=>{lastColors=lighting.update(dt);life.update(dt);life.sync();if(fly){const u=Math.min(1,(performance.now()-fly.start)/1450),s=u*u*(3-2*u);ctx.camera.position.lerpVectors(fly.p,fly.to,s);ctx.controls.target.lerpVectors(fly.t,fly.target,s);ctx.camera.zoom=T.MathUtils.lerp(fly.zoom,fly.z*ctx.fitZoom,s);ctx.camera.updateProjectionMatrix();if(u>=1)fly=null;}});
 window.__sceneReady=true;window.littleWorld={ready:true,ctx,config,layout,simulation,life,water,focus,setTime(mode){ctx.state.timeMode=mode;ctx.state.night=mode==='night';refresh();},reset:()=>focus('city'),diagnostics:()=>({state:{...ctx.state},camera:{position:ctx.camera.position.toArray(),target:ctx.controls.target.toArray(),zoom:ctx.camera.zoom},lighting:lighting.diagnostics(),life:life.diagnostics(),water:water.diagnostics(),simulation:simulation.diagnostics(),render:ctx.renderStats}),dispose(){water.dispose();lighting.dispose();ctx.dispose();}};
 addEventListener('pagehide',e=>{if(!e.persisted)window.littleWorld.dispose();});
}catch(e){console.error(e);document.querySelector('#world-load-status').textContent='Unable to start Chongqing: '+e.message;throw e;}
